import pytest

from duration import parse_duration  # adjust import to your module name


class TestBasicUnits:
    def test_seconds_only(self):
        assert parse_duration("45s") == 45

    def test_minutes_only(self):
        assert parse_duration("90m") == 90 * 60

    def test_hours_only(self):
        assert parse_duration("1h") == 3600

    def test_zero_value(self):
        assert parse_duration("0s") == 0
        assert parse_duration("0h") == 0


class TestCombinedUnits:
    def test_hours_and_minutes(self):
        assert parse_duration("2h30m") == 2 * 3600 + 30 * 60

    def test_all_three_units(self):
        assert parse_duration("1h2m3s") == 3600 + 120 + 3

    def test_minutes_and_seconds(self):
        assert parse_duration("5m30s") == 5 * 60 + 30


class TestOrderAndRepetition:
    def test_units_out_of_order(self):
        # Regex finds all matches regardless of order
        assert parse_duration("30m2h") == 2 * 3600 + 30 * 60

    def test_repeated_units_are_summed(self):
        assert parse_duration("1h1h") == 2 * 3600
        assert parse_duration("10s5s") == 15


class TestEdgeCases:
    def test_empty_string(self):
        assert parse_duration("") == 0

    def test_no_matching_units(self):
        assert parse_duration("hello") == 0
        assert parse_duration("123") == 0  # digits with no unit
        assert parse_duration("h") == 0    # unit with no digits

    def test_unknown_unit_ignored(self):
        assert parse_duration("5d") == 0       # days not supported
        assert parse_duration("5d2h") == 7200  # only the 2h counts

    def test_large_values(self):
        assert parse_duration("1000h") == 1000 * 3600

    def test_multi_digit_values(self):
        assert parse_duration("123s") == 123

    def test_leading_zeros(self):
        assert parse_duration("05m") == 300


class TestLenientParsing:
    """Tests documenting the function's permissive behavior with messy input.

    These pin down current behavior; if stricter validation is added later,
    these tests should be updated intentionally.
    """

    def test_whitespace_between_components(self):
        assert parse_duration("2h 30m") == 2 * 3600 + 30 * 60

    def test_surrounding_garbage(self):
        assert parse_duration("about 5m or so") == 300

    def test_negative_sign_is_ignored(self):
        # The '-' isn't part of the pattern, so "-5m" parses as "5m"
        assert parse_duration("-5m") == 300

    def test_decimal_takes_fractional_part_only(self):
        # "1.5h" matches "5h" (the '1.' is not captured) — a known quirk
        assert parse_duration("1.5h") == 5 * 3600

    def test_uppercase_units_not_matched(self):
        assert parse_duration("2H30M") == 0


class TestTypeErrors:
    def test_none_raises(self):
        with pytest.raises(TypeError):
            parse_duration(None)

    def test_int_raises(self):
        with pytest.raises(TypeError):
            parse_duration(90)


@pytest.mark.parametrize(
    "input_str,expected",
    [
        ("1s", 1),
        ("1m", 60),
        ("1h", 3600),
        ("1h1m1s", 3661),
        ("2h30m", 9000),
        ("90m", 5400),
        ("", 0),
        ("xyz", 0),
    ],
)
def test_parse_duration_parametrized(input_str, expected):
    assert parse_duration(input_str) == expected
```

A few things worth flagging about the function itself, since the tests surfaced them:

1. **No validation** — invalid input silently returns `0` rather than raising. Callers can't distinguish `"0s"` from `"garbage"`.
2. **Decimal quirk** — `"1.5h"` parses as `5h` (18000s), which is almost certainly not what a user intends.
3. **Negative signs ignored** — `"-5m"` returns `300`.
4. **Case sensitivity** — `"2H"` returns `0`; you may want `re.IGNORECASE`.

The `TestLenientParsing` class deliberately documents these quirks so any future fix causes a visible, intentional test update rather than a silent behavior change.

